    v36 = g.math('MULTIPLY', v35, v29)
    v37 = g.vmath('DOT_PRODUCT', v0, v20)
    v38 = g.math('MULTIPLY', v37, v32)
    v39 = g.math('MULTIPLY', v34, v34)
    v40 = g.math('MULTIPLY', v36, v36)
