    v49 = g.inp('_ProjectionParams_w', False, 0.001)
    v50 = g.sep(v48)
    v51 = g.math('MULTIPLY', v47[1], v50[0])
    v52 = g.comb(v47[0], v51, 0.0)
    v53 = g.vmath('ADD', v52, (0.5, 0.5, 0.5))
    v54 = g.sep(v53)
    v55 = g.comb(v54[0], v54[1], 0.0)
    v56 = g.sep(v55)
